#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#include "nwaios/nwaios_lib.h"

#define APP_NAME              "mobilenetv2"
#define MODEL_PATH            "/var/run/nwaios/mobilenetv2/m.bin"
#define COMPUTE_ENGINE        "nsp"
#define EXEC_LOOP_INTERVAL_MS 1000

/* Set by SIGINT/SIGTERM so the inference loop exits cleanly. */
static volatile sig_atomic_t g_shutdown = 0;

static void on_signal(int sig)
{
    (void)sig;
    g_shutdown = 1;
}

/*
 * Async event handler registered via nwaios_lib_init.
 * The framework calls this when compute availability changes,
 * a request begins/ends, or the lib reinitializes.
 */
static void on_nwaios_event(nwaios_callback_msg_id_t msg_id, void *payload)
{
    (void)payload;
    switch (msg_id) {
        case NWAIOS_CB_COMPUTE_AVAILABLE:
            fprintf(stderr, "[%s] compute available\n", APP_NAME);
            break;
        case NWAIOS_CB_COMPUTE_UNAVAILABLE:
            fprintf(stderr, "[%s] compute unavailable\n", APP_NAME);
            break;
        case NWAIOS_CB_REINIT:
            fprintf(stderr, "[%s] lib reinit requested\n", APP_NAME);
            break;
        default:
            break;
    }
}

static int compute_engine_available(const char *name)
{
    struct nwaios_compute compute[NWAIOS_COMPUTE_MAX];
    uint8_t count = 0;
    nwaios_lib_status_t st = nwaios_get_compute_names(compute, &count);
    if (st != NWAIOS_OK) {
        fprintf(stderr, "[%s] nwaios_get_compute_names failed: %d\n", APP_NAME, st);
        return 0;
    }
    for (uint8_t i = 0; i < count; ++i) {
        if (strncmp(compute[i].name, name, NWAIOS_COMPUTE_NAME_MAX) == 0) {
            return 1;
        }
    }
    fprintf(stderr, "[%s] compute engine '%s' not available; have:", APP_NAME, name);
    for (uint8_t i = 0; i < count; ++i) {
        fprintf(stderr, " %s", compute[i].name);
    }
    fprintf(stderr, "\n");
    return 0;
}

int main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    /* 1. Initialize the NWAIOS library for this app. */
    struct nwaios_app_info app_info;
    memset(&app_info, 0, sizeof(app_info));
    strncpy(app_info.name, APP_NAME, sizeof(app_info.name) - 1);
    app_info.client_callback = on_nwaios_event;

    nwaios_lib_status_t st = nwaios_lib_init(&app_info);
    if (st != NWAIOS_OK) {
        fprintf(stderr, "[%s] nwaios_lib_init failed: %d\n", APP_NAME, st);
        return EXIT_FAILURE;
    }

    /* 2. Confirm the requested compute engine is reachable. */
    if (!compute_engine_available(COMPUTE_ENGINE)) {
        nwaios_lib_deinit();
        return EXIT_FAILURE;
    }

    /* 3. Load the model. */
    struct nwaios_model_cfg cfg;
    memset(&cfg, 0, sizeof(cfg));
    strncpy(cfg.path, MODEL_PATH, sizeof(cfg.path) - 1);
    strncpy(cfg.compute_engine, COMPUTE_ENGINE, sizeof(cfg.compute_engine) - 1);
    cfg.sessions = 1;

    struct nwaios_model_ctx *mctx = NULL;
    st = nwaios_model_load(&cfg, &mctx);
    if (st != NWAIOS_OK || mctx == NULL) {
        fprintf(stderr, "[%s] nwaios_model_load failed: %d\n", APP_NAME, st);
        nwaios_lib_deinit();
        return EXIT_FAILURE;
    }
    fprintf(stderr, "[%s] model loaded id=%u path=%s engine=%s\n",
            APP_NAME, mctx->model_id, MODEL_PATH, COMPUTE_ENGINE);

    /* 4. Inference loop — exits on SIGINT/SIGTERM. */
    uint8_t execute_id = 0;
    uint64_t iterations = 0;
    while (!g_shutdown) {
        /* Hook for app-specific input prep — see tensor_io.c */
        if (prepare_inputs(mctx) != 0) {
            fprintf(stderr, "[%s] prepare_inputs failed; aborting\n", APP_NAME);
            break;
        }

        st = nwaios_execute(mctx->model_id, execute_id);
        if (st != NWAIOS_OK) {
            fprintf(stderr, "[%s] nwaios_execute(id=%u) failed: %d\n",
                    APP_NAME, mctx->model_id, st);
            break;
        }

        if (consume_outputs(mctx) != 0) {
            fprintf(stderr, "[%s] consume_outputs failed; aborting\n", APP_NAME);
            break;
        }

        ++iterations;
        if ((iterations % 10) == 0) {
            struct nwaios_app_stats stats;
            memset(&stats, 0, sizeof(stats));
            if (nwaios_get_stats(&stats) == NWAIOS_OK) {
                nwaios_display_stats(&stats);
            }
        }
        usleep(EXEC_LOOP_INTERVAL_MS * 1000);
    }

    /* 5. Tear down. */
    fprintf(stderr, "[%s] shutting down after %llu iterations\n",
            APP_NAME, (unsigned long long)iterations);
    nwaios_model_unload(mctx->model_id);
    nwaios_lib_deinit();
    return EXIT_SUCCESS;
}
